using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool(Name = "echo"), Description("Echoes back the input message.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "get_timestamp"), Description("Returns the current UTC timestamp.")]
    public static string GetTimestamp() => DateTime.UtcNow.ToString("O");
}
