using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        MimeType = "application/json"),
     Description("Returns application configuration settings.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Development",
            Features = new { EnableLogging = true, MaxRetries = 3 }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "api_endpoints",
        MimeType = "application/json"),
     Description("Returns available API endpoint definitions.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/api/users", Method = "GET", Description = "List users" },
            new { Path = "/api/users/{id}", Method = "GET", Description = "Get user by ID" },
        };
        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}
